const existing = new Set(
  $input.all()
    .map(i => (i.json && i.json.name ? String(i.json.name).trim().toLowerCase() : ''))
    .filter(Boolean)
);

const samples = [
  {
    name: 'Austin TX — for sale, 3+ beds, under $600k',
    url: 'https://www.zillow.com/austin-tx/houses/3-_beds/0-600000_price/',
    min_price: 0,
    max_price: 600000,
    min_beds: 3,
    min_baths: 2,
  },
  {
    name: 'Denver CO — for rent, 1+ beds, under $2500',
    url: 'https://www.zillow.com/denver-co/rentals/1-_beds/0-2500_price/',
    min_price: 0,
    max_price: 2500,
    min_beds: 1,
    min_baths: 1,
  },
];

return samples
  .filter(s => !existing.has(s.name.toLowerCase()))
  .map(s => ({ json: s }));

// The ScraperAPI AI Parser already scraped Zillow and extracted the
// listings for us, so there's no HTML parsing left to do here. We just
// coerce the extracted fields to consistent types and keep the listings
// that match this search's price / beds / baths thresholds.

const search = $('Loop Over Search Configs').item.json;
const response = ($input.first().json || {}).response || {};

// The AI Parser returns { parser, version, result }. n8n normally hands us
// `body` already parsed, but guard against a JSON string just in case.
let body = response.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (_) { body = {}; }
}
const result = (body && body.result) || {};
const rawListings = Array.isArray(result.listings) ? result.listings : [];

const num = (v) => {
  if (v === null || v === undefined || v === '') return 0;
  const s = typeof v === 'string' ? v.replace(/[^0-9.]/g, '') : v;
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
};

const toUrl = (u) => {
  if (!u) return '';
  const s = String(u);
  if (s.startsWith('http')) return s;
  return 'https://www.zillow.com' + (s.startsWith('/') ? '' : '/') + s;
};

// Zillow search-results cards don't expose a standalone zpid, so the AI
// Parser returns zpid: null. The stable id lives in the detail URL as
// `<...>/<zpid>_zpid/` — derive it from there, falling back to any
// zpid the parser did manage to extract.
const zpidFrom = (r) => {
  const raw = r.zpid;
  if (raw !== null && raw !== undefined && String(raw).trim() !== '') {
    return String(raw).trim();
  }
  const m = String(r.url || '').match(/(\d+)_zpid/);
  return m ? m[1] : '';
};

const minPrice = num(search.min_price);
const maxPrice = num(search.max_price) || Infinity;
const minBeds = num(search.min_beds);
const minBaths = num(search.min_baths);

const seenInScrape = new Set();
const matching = [];
for (const r of rawListings) {
  const l = {
    zpid: zpidFrom(r),
    address: String(r.address || '').trim(),
    price: num(r.price),
    beds: num(r.beds),
    baths: num(r.baths),
    sqft: num(r.sqft),
    url: toUrl(r.url),
    image_url: String(r.image_url || ''),
  };
  if (!l.zpid || seenInScrape.has(l.zpid)) continue;
  if (l.price > 0 && (l.price < minPrice || l.price > maxPrice)) continue;
  if (l.beds > 0 && l.beds < minBeds) continue;
  if (l.baths > 0 && l.baths < minBaths) continue;
  seenInScrape.add(l.zpid);
  matching.push(l);
}

return [{
  json: {
    search_name: search.name,
    search_url: search.url,
    parsed_count: rawListings.length,
    match_count: matching.length,
    listings: matching,
  },
  pairedItem: { item: 0 },
}];

// Diff the current scrape against ZPIDs already in zillow_seen for this
// search. Output one summary item; fan out to insert and to the loop
// continuation in parallel.

const parse = $('Filter Listings').item.json || {};
const listings = Array.isArray(parse.listings) ? parse.listings : [];

const seenRows = $input.all().map(i => i.json).filter(r => r && r.zpid);
const seenIds = new Set(seenRows.map(r => String(r.zpid)));

const now = new Date().toISOString();
const newListings = [];
for (const l of listings) {
  if (!l.zpid || seenIds.has(String(l.zpid))) continue;
  newListings.push({
    zpid: String(l.zpid),
    search_name: parse.search_name,
    first_seen: now,
    address: l.address || '',
    price: Number(l.price) || 0,
    beds: Number(l.beds) || 0,
    baths: Number(l.baths) || 0,
    sqft: Number(l.sqft) || 0,
    url: l.url || '',
    image_url: l.image_url || '',
  });
}

return [{
  json: {
    search_name: parse.search_name,
    parsed_count: parse.parsed_count || 0,
    match_count: parse.match_count || 0,
    seen_count: seenIds.size,
    new_count: newListings.length,
    new_listings: newListings,
  },
}];

// Group today's new listings by search and render an HTML digest.
// Returns [] when nothing turned up — that short-circuits the Gmail node.

const rows = $input.all().map(i => i.json).filter(r => r && r.zpid);
if (rows.length === 0) return [];

const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtPrice = (n) => !n ? '—' : '$' + Number(n).toLocaleString();
const fmtSqft = (n) => !n ? '—' : Number(n).toLocaleString() + ' sqft';

const groups = new Map();
for (const r of rows) {
  const key = String(r.search_name || 'Unsorted');
  if (!groups.has(key)) groups.set(key, []);
  groups.get(key).push(r);
}

for (const list of groups.values()) {
  list.sort((a, b) => (Number(a.price) || 0) - (Number(b.price) || 0));
}

const today = new Date().toISOString().slice(0, 10);
const total = rows.length;
const subject = `Zillow — ${total} new listing${total === 1 ? '' : 's'} on ${today}`;

const sections = [];
for (const [name, list] of groups) {
  const rowsHtml = list.map(l => `<tr>
  <td>${l.image_url ? `<img src="${esc(l.image_url)}" alt="" width="96" style="display:block;border-radius:4px;" />` : ''}</td>
  <td>
    <div style="font-weight:600;"><a href="${esc(l.url)}" style="color:#0a4d8c;text-decoration:none;">${esc(l.address)}</a></div>
    <div style="color:#555;font-size:13px;">${esc(l.beds)} bd · ${esc(l.baths)} ba · ${esc(fmtSqft(l.sqft))}</div>
  </td>
  <td style="text-align:right;font-weight:600;white-space:nowrap;">${esc(fmtPrice(l.price))}</td>
</tr>`).join('');

  sections.push(`<h3 style="margin:24px 0 8px;">${esc(name)} <span style="color:#888;font-weight:400;">(${list.length})</span></h3>
<table cellpadding="8" cellspacing="0" style="border-collapse:collapse;width:100%;font-size:14px;">
<tbody>${rowsHtml}</tbody>
</table>`);
}

const html = `<div style="font-family:-apple-system,Segoe UI,sans-serif;max-width:760px;">
  <h2 style="margin:0 0 12px;">${esc(subject)}</h2>
  <p style="color:#555;margin:0 0 8px;">Fresh Zillow listings matching your saved searches, gathered automatically by ScraperAPI.</p>
  ${sections.join('\n')}
</div>`;

return [{ json: { count: total, subject, html } }];
